document.querySelectorAll('[data-privacy-row]').forEach(row=>row.querySelectorAll('button').forEach(button=>button.addEventListener('click',()=>row.querySelectorAll('button').forEach(item=>item.classList.toggle('active',item===button)))));
document.querySelectorAll('.settings-choice').forEach(group=>group.querySelectorAll('button').forEach(button=>button.addEventListener('click',()=>group.querySelectorAll('button').forEach(item=>item.classList.toggle('active',item===button)))));
feed.addEventListener('click',event=>{const property=event.target.closest('[data-listing-id]'),userCard=event.target.closest('[data-user-card]'),communityCard=event.target.closest('[data-open-community]'),carouselControl=event.target.closest('[data-carousel-prev],[data-carousel-next]'),action=event.target.closest('[data-action]'),follow=event.target.closest('[data-follow]');if(carouselControl){event.stopPropagation();advanceCarousel(carouselControl.closest('[data-carousel]'),carouselControl.hasAttribute('data-carousel-next')?1:-1);return}if(follow){event.stopPropagation();toggleFollow(follow);return}if(action){event.stopPropagation();if(action.dataset.action==='discard'){const card=action.closest('.feed-card');card.classList.add('discarding');setTimeout(()=>{card.hidden=true;ping('Lo tendremos en cuenta para tus próximos matches')},220);return}action.classList.toggle('saved');action.innerHTML=action.classList.contains('saved')?'♥ <span>Guardado</span>':'♡ <span>Guardar</span>';ping(action.classList.contains('saved')?'Guardado en tus favoritos':'Eliminado de favoritos');return}const imageSave=event.target.closest('.feed-save');if(imageSave){event.stopPropagation();imageSave.classList.toggle('saved');imageSave.textContent=imageSave.classList.contains('saved')?'♥':'♡';ping(imageSave.classList.contains('saved')?'Guardado en tus favoritos':'Eliminado de favoritos');return}const join=event.target.closest('[data-join-community]');if(join){toggleCommunityMembership();return}const vote=event.target.closest('[data-vote]');if(vote){const count=document.querySelector('[data-vote-count]'),active=vote.classList.toggle('voted');count.textContent=Number(count.textContent)+(active?1:-1);return}if(event.target.closest('[data-toast]'))return;if(property)showDetail(listings.find(item=>item.id===Number(property.dataset.listingId)));else if(userCard)open(userProfileModal);else if(communityCard)openCommunity()});
feed.addEventListener('keydown',event=>{if(event.key!=='Enter')return;if(event.target.matches('[data-listing-id]'))showDetail(listings.find(item=>item.id===Number(event.target.dataset.listingId)));if(event.target.matches('[data-user-card]'))open(userProfileModal);if(event.target.matches('[data-open-community]'))openCommunity()});
document.querySelector('.visible-groups [data-open-community]').addEventListener('click',()=>openCommunity());
document.querySelector('#exploreFilters').addEventListener('click',()=>open(exploreFilterModal));
document.querySelectorAll('[data-explore-view]').forEach(button=>button.addEventListener('click',()=>{const map=button.dataset.exploreView==='map';document.querySelectorAll('[data-explore-view]').forEach(item=>item.classList.toggle('active',item===button));document.querySelector('#exploreList').hidden=map;document.querySelector('#exploreMap').hidden=!map}));
document.querySelector('#exploreSort').addEventListener('change',event=>ping(`Ordenado por ${event.target.options[event.target.selectedIndex].textContent.toLowerCase()}`));
document.querySelector('#exploreList').addEventListener('click',event=>{const save=event.target.closest('[data-explore-save]'),card=event.target.closest('[data-listing-id]');if(save){save.classList.toggle('saved');save.textContent=save.classList.contains('saved')?'♥':'♡';ping(save.classList.contains('saved')?'Guardado en favoritos':'Eliminado de favoritos');return}if(card)showDetail(listings.find(item=>item.id===Number(card.dataset.listingId)))});
document.querySelectorAll('[data-map-listing]').forEach(pin=>pin.addEventListener('click',()=>{document.querySelectorAll('[data-map-listing]').forEach(item=>item.classList.toggle('active',item===pin));const item=listings.find(listing=>listing.id===Number(pin.dataset.mapListing));document.querySelector('#mapMiniCard').innerHTML=`<img src="${item.img}" alt="${item.title}"><div><span>${item.match}% MATCH</span><h2>${item.zone} · ${item.id===3?'Piso entero':'Habitación'}</h2><p><b>${item.price} €</b> / mes</p></div>`}));
document.querySelector('#mapMiniCard').addEventListener('click',()=>{const pin=document.querySelector('[data-map-listing].active');showDetail(listings.find(item=>item.id===Number(pin.dataset.mapListing)))});
function openReport(target){document.querySelector('#reportTarget').textContent=`Sobre: ${target}`;document.querySelectorAll('.report-reasons button').forEach(button=>button.setAttribute('aria-checked','false'));document.querySelector('#submitReport').disabled=true;open(reportModal)}
document.querySelectorAll('.report-reasons button').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.report-reasons button').forEach(item=>item.setAttribute('aria-checked',String(item===button)));document.querySelector('#submitReport').disabled=false}));
document.querySelector('#submitReport').addEventListener('click',()=>{reportCount++;document.querySelector('#reportsStatus').textContent=`${reportCount} en revisión`;closeAll();ping('Reporte enviado · Gracias por ayudarnos a cuidar Rooms')});
document.querySelector('#confirmBlock').addEventListener('click',()=>{blockedCount++;document.querySelector('#blockedUsersCount').textContent=`${blockedCount} persona bloqueada`;personConnected=false;closeAll();ping('Usuario bloqueado y ocultado de tus recomendaciones')});
document.querySelector('#blockedUsers').addEventListener('click',()=>ping(blockedCount?'1 usuario bloqueado · Puedes desbloquearlo cuando quieras':'No tienes usuarios bloqueados'));
document.querySelector('#myReports').addEventListener('click',()=>ping(reportCount?`${reportCount} reporte en revisión`:'No tienes reportes activos'));
document.querySelectorAll('[data-admin-action]').forEach(button=>button.addEventListener('click',()=>{const action=button.dataset.adminAction;if(action==='reports'){openReport('contenido reportado en Vivir en Chamberí');return}const messages={pin:'Publicación fijada',remove:'Contenido eliminado y acción registrada',expel:'Usuario expulsado de la comunidad',requests:'3 solicitudes listas para revisar'};ping(messages[action])}));
document.querySelector('#confirmExternalAvailable').addEventListener('click',event=>{event.currentTarget.textContent='Disponibilidad confirmada ✓';event.currentTarget.disabled=true;document.querySelectorAll('.availability-warning').forEach(item=>item.textContent='CONFIRMADO POR LA COMUNIDAD');ping('Gracias · disponibilidad actualizada')});
document.querySelectorAll('[data-empty-action]').forEach(button=>button.addEventListener('click',()=>{if(button.dataset.emptyAction==='similar'){document.querySelector('#exploreSearch').value='';document.querySelector('#exploreEmpty').hidden=true;document.querySelector('#exploreList').hidden=false;document.querySelectorAll('.compact-property,#exploreList .explore-exception,#exploreList .explore-count').forEach(item=>item.hidden=false);ping('Mostrando opciones similares');return}open(exploreFilterModal)}));
const offlineBanner=document.createElement('div');offlineBanner.className='offline-banner';offlineBanner.hidden=true;offlineBanner.innerHTML='<b>Sin conexión</b><span>Te mostramos el contenido guardado en este dispositivo.</span>';document.body.appendChild(offlineBanner);window.addEventListener('offline',()=>offlineBanner.hidden=false);window.addEventListener('online',()=>{offlineBanner.hidden=true;ping('Conexión recuperada')});
document.addEventListener('click',event=>{const report=event.target.closest('[data-report]'),block=event.target.closest('[data-block-user]'),externalInfo=event.target.closest('[data-external-info]');if(report){event.preventDefault();event.stopPropagation();openReport(report.dataset.report);return}if(block){event.preventDefault();event.stopPropagation();open(blockModal);return}if(externalInfo){event.preventDefault();event.stopPropagation();open(externalInfoModal)}});
document.addEventListener('click',event=>{const detailCarouselControl=event.target.closest('#detailModal [data-carousel-prev],#detailModal [data-carousel-next]'),detailSave=event.target.closest('[data-detail-save]'),follow=event.target.closest('#userProfileModal [data-follow]'),activityTab=event.target.closest('[data-activity-tab]'),openMatchButton=event.target.closest('[data-open-match]'),returnProfile=event.target.closest('[data-return-profile]'),ruleToggle=event.target.closest('[data-rule-toggle]'),toastTarget=event.target.closest('[data-toast]');if(detailCarouselControl){advanceCarousel(detailCarouselControl.closest('[data-carousel]'),detailCarouselControl.hasAttribute('data-carousel-next')?1:-1);return}if(detailSave){detailSave.classList.toggle('saved');detailSave.textContent=detailSave.classList.contains('saved')?'♥':'♡';ping(detailSave.classList.contains('saved')?'Guardado en tus favoritos':'Eliminado de favoritos');return}if(follow){toggleFollow(follow);return}if(openMatchButton){userProfileModal.classList.remove('open');userProfileModal.setAttribute('aria-hidden','true');open(matchModal);return}if(returnProfile){matchModal.classList.remove('open');matchModal.setAttribute('aria-hidden','true');open(userProfileModal);return}if(activityTab){document.querySelectorAll('[data-activity-tab]').forEach(item=>item.classList.toggle('active',item===activityTab));const copy={Publicaciones:['HACE 2 DÍAS','“Busco recomendaciones de zonas tranquilas y bien conectadas por Chamberí.”','14 respuestas · 32 votos'],Anuncios:['ACTIVO','Busco habitación luminosa para entrar en septiembre.','91% perfil completado'],Compartidos:['HACE 1 SEMANA','“Guía rápida para mudarte a Chamberí.”','Guardado por 46 personas'],Reseñas:['HACE 3 SEMANAS','“Lucía cuidó mucho la casa y la convivencia fue facilísima.”','5,0 · Compañera verificada']}[activityTab.dataset.activityTab];document.querySelector('#activityPreview').innerHTML=`<small>${copy[0]}</small><p>${copy[1]}</p><span>${copy[2]}</span>`;return}if(ruleToggle){const extra=document.querySelector('.extra-rule'),showing=extra.hidden;extra.hidden=!showing;ruleToggle.textContent=showing?'Ver menos':'Ver todas';return}if(event.target.matches('[data-close]'))closeAll();if(toastTarget){ping(toastTarget.dataset.toast);if(toastTarget.closest('#publishModal,#feedFilterModal,.detail-fixed-cta'))closeAll()}});document.addEventListener('keydown',event=>{if(event.key==='Escape')closeAll()});
